    k2[i] = f(x + std::vector<double>(k1.size(), 0.0) + k1 * 0.5, t + 0.5 * h)[i];
}
std::vector<double> k3 = f(x + std::vector<double>(k2.size(), 0.0), t + 0.5 * h);
for (int i = 0; i < k2.size(); i++) {
    k3[i] = f(x + std::vector<double>(k2.size(), 0.0) + k2 * 0.5, t + 0.5 * h)[i];
}
std::vector<double> k4 = f(x + std::vector<double>(k3.size(), 0.0), t + h);
for (int i = 0; i < k3.size(); i++) {
    k4[i] = f(x + std::vector<double>(k3.size(), 0.0) + k3 * 1.0, t + h)[i];
}
std::vector<double> result = x;
for (int i = 0; i < x.size(); i++) {
    result[i] = x[i] + (k1[i] + 2.0 * k2[i] + 2.0 * k3[i] + k4[i]) * (h / 6.0);
}
return result;

